INSERT INTO `pages` (`id`, `title`, `slug`, `type`, `category_id`, `content`, `seo_title`, `seo_description`, `seo_keywords`, `og_title`, `og_description`, `og_image`, `created_at`, `updated_at`, `schema_type`, `faqs`) VALUES
  ('8578c405-a7db-4a9d-a795-f0fa51f47b47', 'Contacts', 'contacts', 'static', NULL, '<div class=\"wp-block-group\">\n<h3 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px\">Feel&nbsp;Free&nbsp;to&nbsp;Contact&nbsp;Me</h3>\n\n\n\n<p class=\"has-text-align-center has-secondary-color has-text-color has-link-color\" style=\"margin-top:10px;font-size:16px;line-height:1.55\">At <strong>Sikar Education Hub, </strong>we\'re committed to helping students, parents, educators, and institutions with reliable educational information. Whether you have a question, suggestion, partnership inquiry, or would like to report an update, we\'d be happy to hear from you.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Get in Touch</h2>\n\n\n\n<p class=\"has-text-align-center has-secondary-color has-text-color has-link-color\" style=\"margin-top:10px;font-size:16px;line-height:1.55\">Have a question about schools, coaching institutes, colleges, admissions, or educational resources? Our team is here to assist you.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Contact Information</h3>\n\n\n\n<p><strong>Website:</strong> <a href=\"https://sikarshiksha.com\">https://sikareducationhub.com/</a></p>\n\n\n\n<p><strong>Address:</strong> Sikar, Rajasthan, India</p>\n\n\n\n<h2 class=\"wp-block-heading\">We Can Help You With</h2>\n\n\n\n<ul class=\"wp-block-list\">\n<li>School and coaching-related information</li>\n\n\n\n<li>College and admission guidance</li>\n\n\n\n<li>Website feedback and suggestions</li>\n\n\n\n<li>Corrections or updates to published content</li>\n\n\n\n<li>Advertising and brand collaborations</li>\n\n\n\n<li>Business partnerships</li>\n\n\n\n<li>Guest posting and media inquiries</li>\n\n\n\n<li>Technical support</li>\n</ul>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n\n\n\n<h2 class=\"wp-block-heading\">Business &amp; Partnership Enquiries</h2>\n\n\n\n<p>If you\'re a school, coaching institute, college, educational organization, or business interested in collaborating with <strong>Sikar Education Hub</strong>, we\'d love to discuss partnership opportunities.</p>\n\n\n\n<p>Please include the following details in your email:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Organization Name</li>\n\n\n\n<li>Contact Person</li>\n\n\n\n<li>Purpose of Inquiry</li>\n\n\n\n<li>Website (if applicable)</li>\n\n\n\n<li>Contact Number</li>\n</ul>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n\n\n\n<h2 class=\"wp-block-heading\">Report an Update or Correction</h2>\n\n\n\n<p>We strive to keep all educational information accurate and up to date. If you notice any incorrect information regarding admissions, fees, facilities, rankings, or institution details, please let us know. Our editorial team will review your request and make updates where appropriate.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n\n\n\n<h2 class=\"wp-block-heading\">Response Time</h2>\n\n\n\n<p>We aim to respond to all genuine inquiries within <strong>24–48 business hours</strong>.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n\n\n\n<h2 class=\"wp-block-heading\">Follow Us</h2>\n\n\n\n<p>Stay updated with the latest news on schools, coaching institutes, admissions, competitive exams, and educational trends by following <strong>Sikar Education Hub</strong> on our social media channels.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n\n\n\n<h2 class=\"wp-block-heading\">Our Commitment</h2>\n\n\n\n<p>We value every message from our readers and partners. Your feedback helps us improve our content and continue providing accurate, helpful, and trustworthy educational resources for students and parents across Sikar, Rajasthan, and India.</p>\n</div>\n\n\n\n<div class=\"wp-block-group is-style-cs-contact-form\">\n<div class=\"wp-block-columns has-white-background-color has-background\" style=\"border-style:none;border-width:0px;border-radius:16px;margin-top:32px;padding-top:48px;padding-right:48px;padding-bottom:48px;padding-left:48px;box-shadow:var(--wp--preset--shadow--standard)\">\n<div class=\"wp-block-column is-vertically-aligned-top\">\n<div class=\"wp-block-group is-style-cs-contact-form\">\n<h5 class=\"wp-block-heading\" style=\"margin-bottom:20px\">Ready to Get Started?</h5>\n\n\n\n[wpforms id=\"970\" title=\"false\"]\n</div>\n</div>\n</div>\n</div>', 'Contacts', '\nFeel&nbsp;Free&nbsp;to&nbsp;Contact&nbsp;Me\n\n\n\nAt Sikar Education Hub, we\'re committed to helping students, parents, educators, and institutions with reliable...', NULL, 'Contacts', '\nFeel&nbsp;Free&nbsp;to&nbsp;Contact&nbsp;Me\n\n\n\nAt Sikar Education Hub, we\'re committed to helping students, parents, educators, and institutions with reliable...', NULL, '2024-09-27 07:10:19', '2026-07-04 06:45:49', 'Article', NULL),
  ('a8bd4e95-2561-42b3-97d2-a23520ecaf62', 'About', 'about', 'static', NULL, '<h1 class=\"wp-block-heading has-text-align-center is-style-cs-heading-gradient\" style=\"margin-bottom:64px;letter-spacing:-0.05em\">Hey, <span>Wonderful</span> to Meet Yo</h1>\n\n\n\n<p>Welcome to <strong>Sikar Education Hub</strong>, your trusted education information platform dedicated to helping students, parents, and educators make informed academic decisions. We believe that choosing the right school, coaching institute, college, or career path is one of the most important decisions in a student\'s life. Our mission is to simplify that journey by providing accurate, research-driven, and easy-to-understand educational content.</p>\n\n\n\n<p>Sikar has emerged as one of India\'s fastest-growing education hubs, attracting thousands of students every year for school education, IIT-JEE, NEET, CLAT, CUET, NDA, RAS, and other competitive examinations. At Sikar Shiksha, we aim to become the most comprehensive digital guide for anyone exploring educational opportunities in Sikar and across Rajasthan.</p>\n\n\n\n<h2 class=\"wp-block-heading\">What We Do</h2>\n\n\n\n<p>Our platform publishes well-researched guides, comparisons, rankings, and educational resources to help students and parents evaluate institutions based on multiple factors rather than advertisements or hearsay. We focus on delivering practical information that supports better decision-making.</p>\n\n\n\n<p>Our content includes:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>School comparison guides</li>\n\n\n\n<li>Coaching institute reviews</li>\n\n\n\n<li>College information</li>\n\n\n\n<li>Admission guides</li>\n\n\n\n<li>Entrance exam preparation resources</li>\n\n\n\n<li>Scholarship and career guidance</li>\n\n\n\n<li>Hostel and student accommodation information</li>\n\n\n\n<li>Education news and updates</li>\n\n\n\n<li>Parent-focused educational resources</li>\n\n\n\n<li>Student success stories and learning tips</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Our Areas of Coverage</h2>\n\n\n\n<p>We cover a wide range of educational topics, including:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>CBSE, RBSE, ICSE &amp; English Medium Schools</li>\n\n\n\n<li>Residential &amp; Boarding Schools</li>\n\n\n\n<li>IIT-JEE Coaching Institutes</li>\n\n\n\n<li>NEET Coaching Institutes</li>\n\n\n\n<li>CLAT Coaching</li>\n\n\n\n<li>CUET Preparation</li>\n\n\n\n<li>NDA, CDS &amp; Defence Academies</li>\n\n\n\n<li>RAS &amp; Government Exam Coaching</li>\n\n\n\n<li>Colleges and Universities</li>\n\n\n\n<li>Student Hostels &amp; Living Facilities</li>\n\n\n\n<li>School and College Admissions</li>\n\n\n\n<li>Career Planning &amp; Counselling</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Our Mission</h2>\n\n\n\n<p>Our mission is to empower students and parents with transparent, reliable, and comprehensive educational information so they can confidently choose the right institution based on their goals, interests, and aspirations.</p>\n\n\n\n<p>We strive to bridge the information gap by presenting educational data in a clear, unbiased, and accessible format.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Our Vision</h2>\n\n\n\n<p>To become Rajasthan\'s most trusted education information platform by providing authentic educational insights, expert guidance, and valuable resources that help every student achieve academic success.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Our Values</h2>\n\n\n\n<h3 class=\"wp-block-heading\">Student First</h3>\n\n\n\n<p>Every article, guide, and comparison is created with students\' and parents\' needs in mind.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Transparency</h3>\n\n\n\n<p>We aim to present educational information objectively, encouraging readers to verify details directly with institutions before making final decisions.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Quality Content</h3>\n\n\n\n<p>Our editorial team focuses on creating informative, well-structured, and regularly updated content that aligns with the latest educational developments.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Continuous Learning</h3>\n\n\n\n<p>Education evolves constantly, and so do we. We continuously update our content to reflect new admission policies, examination changes, and educational trends.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Why Choose Sikar Shiksha?</h2>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Comprehensive education guides</li>\n\n\n\n<li>Institution comparison articles</li>\n\n\n\n<li>Parent-focused decision support</li>\n\n\n\n<li>Student-friendly content</li>\n\n\n\n<li>SEO-optimized educational resources</li>\n\n\n\n<li>Coverage of schools, coaching institutes, colleges, and competitive exams</li>\n\n\n\n<li>Regularly updated educational information</li>\n\n\n\n<li>Easy-to-understand articles and practical guidance</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Our Commitment</h2>\n\n\n\n<p>At <strong><strong>Sikar Education Hub</strong></strong>, we are committed to providing informative and educational content designed to help students and parents make informed decisions. While we strive for accuracy and keep our content updated, admission policies, fees, facilities, eligibility criteria, and institutional offerings may change over time. We encourage readers to verify the latest information directly with the respective institutions or official authorities before making admission or career decisions.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Join Our Educational Journey</h2>\n\n\n\n<p>Whether you\'re searching for the best school, coaching institute, college, or career guidance, <strong><strong>Sikar Education Hub</strong></strong> is here to support your educational journey with reliable information, expert insights, and practical resources.</p>\n\n\n\n<p>Together, let\'s make informed educational choices and build a brighter future.</p>\n\n\n\n<div class=\"wp-block-group alignwide is-style-cs-about-page\">\n<div class=\"wp-block-group has-white-background-color has-background\" style=\"border-radius:16px;padding-top:40px;padding-right:40px;padding-bottom:40px;padding-left:40px;box-shadow:var(--wp--preset--shadow--standard)\">\n<figure class=\"wp-block-image alignleft size-full is-resized\"><img src=\"http://revision.codesupply.co/revision/wp-content/uploads/sites/2/2024/10/about-icon-001.webp\" alt=\"\" class=\"wp-image-486\" style=\"width:40px\"/></figure>\n\n\n\n<h5 class=\"wp-block-heading has-text-align-left\" style=\"margin-top:0px;margin-bottom:8px;padding-top:28px\">Empowering Innovation</h5>\n\n\n\n<p class=\"has-text-align-left has-secondary-color has-text-color has-link-color\" style=\"margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;font-size:16px\">We consistently push the boundaries of technology, leading to unique and effective solutions.</p>\n</div>\n\n\n\n<div class=\"wp-block-group has-white-background-color has-background\" style=\"border-radius:16px;padding-top:40px;padding-right:40px;padding-bottom:40px;padding-left:40px;box-shadow:var(--wp--preset--shadow--standard)\">\n<figure class=\"wp-block-image alignleft size-full is-resized\"><img src=\"http://revision.codesupply.co/revision/wp-content/uploads/sites/2/2024/10/about-icon-002.webp\" alt=\"\" class=\"wp-image-487\" style=\"width:40px\"/></figure>\n\n\n\n<h5 class=\"wp-block-heading has-text-align-left\" style=\"margin-top:0px;margin-bottom:8px;padding-top:28px\">Community-Centric Approach</h5>\n\n\n\n<p class=\"has-text-align-left has-secondary-color has-text-color has-link-color\" style=\"margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;font-size:16px\">Our commitment to giving back not only enhances their reputation but also strengthens ties within the community.</p>\n</div>\n\n\n\n<div class=\"wp-block-group has-white-background-color has-background\" style=\"border-radius:16px;padding-top:40px;padding-right:40px;padding-bottom:40px;padding-left:40px;box-shadow:var(--wp--preset--shadow--standard)\">\n<figure class=\"wp-block-image alignleft size-full is-resized\"><img src=\"http://revision.codesupply.co/revision/wp-content/uploads/sites/2/2024/10/about-icon-003.webp\" alt=\"\" class=\"wp-image-488\" style=\"width:40px\"/></figure>\n\n\n\n<h5 class=\"wp-block-heading has-text-align-left\" style=\"margin-top:0px;margin-bottom:8px;padding-top:28px\">Flexibility &amp; Adaptability</h5>\n\n\n\n<p class=\"has-text-align-left has-secondary-color has-text-color has-link-color\" style=\"margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;font-size:16px\">Our team agile work environment allows them to quickly adapt to changing market needs.</p>\n</div>\n</div>\n\n\n\n<p></p>', 'About', 'Hey, Wonderful to Meet Yo\n\n\n\nWelcome to Sikar Education Hub, your trusted education information platform dedicated to helping students, parents, and educators m...', NULL, 'About', 'Hey, Wonderful to Meet Yo\n\n\n\nWelcome to Sikar Education Hub, your trusted education information platform dedicated to helping students, parents, and educators m...', NULL, '2024-10-02 08:30:18', '2026-07-04 06:41:58', 'Article', NULL);
